window.ScripturaLexicons.LSJ.rowsHtml+="<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2065\" data-lsj-orig-id=\"n2065\" data-lsj-ordinal=\"2101\"><td class=\"greek\">ἀθρυψία</td><td>LSJ</td><td>Vida simples, existência sem luxo.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2066\" data-lsj-orig-id=\"n2066\" data-lsj-ordinal=\"2102\"><td class=\"greek\">ἀθυμέω</td><td>LSJ</td><td>Desanimar, perder a coragem, desesperar-se; recear intensamente, conforme a construção.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2067\" data-lsj-orig-id=\"n2067\" data-lsj-ordinal=\"2103\"><td class=\"greek\">ἀθυμητέον</td><td>LSJ</td><td>É preciso perder o ânimo; sobretudo na negação «não se deve desanimar».</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2068\" data-lsj-orig-id=\"n2068\" data-lsj-ordinal=\"2104\"><td class=\"greek\">ἀθυμία</td><td>LSJ</td><td>Falta de ânimo, fraqueza de espírito, desalento, desânimo.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2069\" data-lsj-orig-id=\"n2069\" data-lsj-ordinal=\"2105\"><td class=\"greek\">ἀθυμίαστος</td><td>LSJ</td><td>Não consagrado por rito.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2070\" data-lsj-orig-id=\"n2070\" data-lsj-ordinal=\"2106\"><td class=\"greek\">ἀθυμίατος</td><td>LSJ</td><td>Incapaz de exalar vapor.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2071\" data-lsj-orig-id=\"n2071\" data-lsj-ordinal=\"2107\"><td class=\"greek\">ἄθυμος</td><td>LSJ</td><td>Desanimado, pusilânime, sem vigor; desencorajador; sem ira ou paixão, em uso especial.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2072\" data-lsj-orig-id=\"n2072\" data-lsj-ordinal=\"2108\"><td class=\"greek\">ἀθυμόω</td><td>LSJ</td><td>Desanimar alguém.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2073\" data-lsj-orig-id=\"n2073\" data-lsj-ordinal=\"2109\"><td class=\"greek\">ἀθυρεύεσθαι</td><td>LSJ</td><td>Glosas: brincar, unir ou misturar, saltitar.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2074\" data-lsj-orig-id=\"n2074\" data-lsj-ordinal=\"2110\"><td class=\"greek\">ἄθυρμα</td><td>LSJ</td><td>Brinquedo, objeto de diversão; adorno; deleite, alegria; passatempo.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2075\" data-lsj-orig-id=\"n2075\" data-lsj-ordinal=\"2111\"><td class=\"greek\">ἀθυρμάτιον</td><td>LSJ</td><td>Brinquedinho, pequeno objeto de afeição; favorito.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2076\" data-lsj-orig-id=\"n2076\" data-lsj-ordinal=\"2112\"><td class=\"greek\">ἀθυρογλωττία</td><td>LSJ</td><td>Tagarelice insolente.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2077\" data-lsj-orig-id=\"n2077\" data-lsj-ordinal=\"2113\"><td class=\"greek\">ἀθυρόγλωττος</td><td>LSJ</td><td>Tagarela que não mantém a boca fechada.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2078\" data-lsj-orig-id=\"n2078\" data-lsj-ordinal=\"2114\"><td class=\"greek\">ἀθυρονόμος</td><td>LSJ</td><td>Que faz pouco das leis.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2079\" data-lsj-orig-id=\"n2079\" data-lsj-ordinal=\"2115\"><td class=\"greek\">ἄθυρος</td><td>LSJ</td><td>Sem porta, aberto, sem controle.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2080\" data-lsj-orig-id=\"n2080\" data-lsj-ordinal=\"2116\"><td class=\"greek\">ἀθυροστομία</td><td>LSJ</td><td>Tagarelice imprudente, insolência verbal.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2081\" data-lsj-orig-id=\"n2081\" data-lsj-ordinal=\"2117\"><td class=\"greek\">ἀθυρόστομος</td><td>LSJ</td><td>Que fala continuamente, tagarela.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2082\" data-lsj-orig-id=\"n2082\" data-lsj-ordinal=\"2118\"><td class=\"greek\">ἄθυρσις</td><td>LSJ</td><td>Brincadeira, diversão, festa.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2083\" data-lsj-orig-id=\"n2083\" data-lsj-ordinal=\"2119\"><td class=\"greek\">ἄθυρσος</td><td>LSJ</td><td>Sem tirso, desprovido do bastão ritual.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2084\" data-lsj-orig-id=\"n2084\" data-lsj-ordinal=\"2120\"><td class=\"greek\">ἀθύρω</td><td>LSJ</td><td>Brincar, divertir-se; cantar em tom lúdico; zombar.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2085\" data-lsj-orig-id=\"n2085\" data-lsj-ordinal=\"2121\"><td class=\"greek\">ἀθύρωτος</td><td>LSJ</td><td>Não provido de portas; talvez sem aberturas ou não fechado; desimpedido.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2086\" data-lsj-orig-id=\"n2086\" data-lsj-ordinal=\"2122\"><td class=\"greek\">ἀθύσσει</td><td>LSJ</td><td>Glosas: misturar, unir; dar palmadas, esbofetear.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2087\" data-lsj-orig-id=\"n2087\" data-lsj-ordinal=\"2123\"><td class=\"greek\">ἄθυστος</td><td>LSJ</td><td>Equivalente a ἄθυτος, não sacrificado.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2088\" data-lsj-orig-id=\"n2088\" data-lsj-ordinal=\"2124\"><td class=\"greek\">ἄθυτος</td><td>LSJ</td><td>Não oferecido em sacrifício; omitido, malsucedido ou impróprio para sacrifício; sem oferenda ritual.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2089\" data-lsj-orig-id=\"n2089\" data-lsj-ordinal=\"2125\"><td class=\"greek\">ἀθώητος</td><td>LSJ</td><td>Impune, sem penalidade; glosa de ἀζημίωτος.</td><td>LSJ</td></tr>";
